def is_valid_ipv4(s: str) -> bool:
    if not s or any(c in ' \t\n' for c in s):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # Check no signs, whitespace, or other non-digit characters (except the digits themselves)
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
        # No leading zeros allowed except for "0" itself
        if len(part) > 1 and part[0] == '0':
            return False
    return True
```

